// Style Dictionary: DTCG tokens in /tokens -> TypeScript the MUI theme can import.
// Writes three generated files into src/theme/generated/. Never edit those by hand.
//
//   palette.light.ts  MUI palette for the light colour scheme
//   palette.dark.ts   MUI palette for the dark colour scheme
//   base.ts           shape, spacing and typography
//
// Light and dark are separate Style Dictionary runs because both semantic files use the same token
// names (palette.primary.main and so on). Each run sees the primitives plus one scheme.
import StyleDictionary from 'style-dictionary';

const HEADER = '// Generated by style-dictionary.config.mjs from /tokens. Do not edit. Run `npm run tokens:build`.\n';

const nest = (tokens, drop) => {
  const out = {};
  for (const t of tokens) {
    const path = t.path.slice(drop);
    let o = out;
    for (const k of path.slice(0, -1)) o = o[k] ??= {};
    o[path.at(-1)] = t.$value;
  }
  return out;
};
const ts = (name, value) => `export const ${name} = ${JSON.stringify(value, null, 2)} as const;\n`;

StyleDictionary.registerFormat({
  name: 'northwind/mui-palette',
  format: ({ dictionary, options }) => HEADER + ts(options.exportName, nest(dictionary.allTokens, 1)),
});

StyleDictionary.registerFormat({
  name: 'northwind/mui-base',
  format: ({ dictionary }) => {
    const get = p => dictionary.allTokens.find(t => t.path.join('.') === p)?.$value;
    const dim = v => (typeof v === 'object' ? v.value : v);
    const variants = {};
    for (const t of dictionary.allTokens.filter(t => t.path[1] === 'variant')) {
      const v = t.$value;
      variants[t.path[2]] = {
        fontWeight: v.fontWeight,
        fontSize: `${+v.fontSize.value.toFixed(4)}${v.fontSize.unit}`,
        lineHeight: v.lineHeight,
        letterSpacing: `${v.letterSpacing.value}${v.letterSpacing.unit}`,
        ...(t.$extensions?.['com.northwind']?.textTransform ? { textTransform: t.$extensions['com.northwind'].textTransform } : {}),
      };
    }
    const family = get('typography.fontFamily');
    return HEADER +
      ts('shape', { borderRadius: dim(get('shape.borderRadius')) }) +
      ts('spacingUnit', dim(get('spacing.unit'))) +
      ts('typography', {
        fontFamily: Array.isArray(family) ? family.join(', ') : family,
        fontWeightLight: get('typography.fontWeight.light'),
        fontWeightRegular: get('typography.fontWeight.regular'),
        fontWeightMedium: get('typography.fontWeight.medium'),
        fontWeightBold: get('typography.fontWeight.bold'),
        ...variants,
      });
  },
});

const run = (source, files) =>
  new StyleDictionary({
    source,
    log: { verbosity: 'silent' },
    platforms: { ts: { transforms: [], buildPath: 'src/theme/generated/', files } },
  }).buildAllPlatforms();

for (const scheme of ['light', 'dark']) {
  await run(['tokens/primitives/**/*.json', `tokens/semantic/${scheme}.tokens.json`], [{
    destination: `palette.${scheme}.ts`,
    format: 'northwind/mui-palette',
    filter: t => t.path[0] === 'palette',
    options: { exportName: `${scheme}Palette` },
  }]);
}
await run(['tokens/base/**/*.json'], [{ destination: 'base.ts', format: 'northwind/mui-base' }]);

console.log('Theme files written to src/theme/generated/.');
